// 测试用的最小桩：只让 `defineTool` 原样返回定义。
//
// 真实的 @deepseek-ai/dsh-tools 在 DSH 宿主里（app.asar），独立 node 进程解析不到。
// 这里只用来验证插件自己的 action 分发、错误码与渲染；参数/输出 schema 的真实校验
// 由安装到 profile 之后的端到端调用覆盖。

'use strict'

function defineTool (definition) {
  if (definition === null || typeof definition !== 'object') throw new TypeError('defineTool 需要对象')
  if (typeof definition.name !== 'string' || definition.name === '') throw new TypeError('defineTool 需要 name')
  if (typeof definition.execute !== 'function') throw new TypeError('defineTool 需要 execute')
  return definition
}

module.exports = { defineTool }
